// Tool registers a tool with a typed handler in one call. T is the args struct
// the model's JSON tool-call arguments decode into; R is the handler's typed
// return value (JSON-encoded before being sent back to the model as the tool
// result). Bind both explicitly at the call site with `of T and R`.
//
// Use with RunTools to dispatch — RunTools reads handlers registered here and
// does the parse / call / encode dance per tool call. The lower-level
// ExecuteToolCalls + external handler map remains available for callers that
// need raw JSON-string handlers.
//
// Example:
//
//	type WeatherArgs
//	    Latitude string
//	    Longitude string
//
//	type WeatherResult
//	    TempC float
//	    Summary string
//
//	client := chat.New("openai:gpt-4o-mini")
//	    |> chat.WithTool of WeatherArgs and WeatherResult("get_weather", "Current weather", schema,
//	        func(args: WeatherArgs) (WeatherResult, error)
//	            return weatherFor(args.Latitude, args.Longitude), empty)
func WithTool[T any, R any](c Client, name string, description string, schema any, handler func(T) (R, error)) Client {
	c = AddTool(c, name, description, schema)
	if c.toolHandlers == nil {
		c.toolHandlers = make(map[string]func(string) (string, error))
	}
	c.toolHandlers[name] = func(argsJSON string) (string, error) {
		var args T
		if argsJSON != "" {
			parseErr := json.ParseInto(argsJSON, &args)
			if parseErr != nil {
				return "", parseErr
			}
		}
		result, handlerErr := handler(args)
		if handlerErr != nil {
			return "", handlerErr
		}
		encoded, encErr := json.Bytes(result)
		if encErr != nil {
			return "", encErr
		}
		return string(encoded), nil
	}
	return c
}

// RunTools dispatches the tool calls in comp against handlers registered via
// Tool. The assistant message and each tool result are appended to the client
// so the next Send/Ask sees a well-formed multi-turn conversation.
//
// Returns an error if the model invokes a tool that wasn't registered, or if
// a handler returns a non-nil error.
func RunTools(c Client, comp Completion) (Client, error) {
	if len(comp.Choices) == 0 {
		return c, nil
	}
	msg := comp.Choices[0].Message
	assistantMsg := Message{Role: MessageRoleAssistant, Content: msg.Content, ToolCalls: msg.ToolCalls}
	c.messages = append(c.messages, assistantMsg)
	for _, call := range msg.ToolCalls {
		handler, ok := c.toolHandlers[call.Function.Name]
		if !ok {
			return c, fmt.Errorf("no handler registered for tool: %v", call.Function.Name)
		}
		result, callErr := handler(call.Function.Arguments)
		if callErr != nil {
			return c, callErr
		}
		toolMsg := Message{Role: MessageRoleTool, Content: result, ToolCallID: call.ID}
		c.messages = append(c.messages, toolMsg)
	}
	return c, nil
}

