type streamFinal struct {
	Completion Completion
	Err        error
}

// AskStream adds a user message, opens a streaming request, and returns a
// channel of unified `llm.StreamEvent` values plus a `collect` closure that
// yields the assembled `Completion` (full text + tool calls + finish reason)
// once the stream finishes. The channel closes when the provider sends
// [DONE] or an error terminates the stream; pre-stream errors (resolve /
// network / HTTP 4xx/5xx) surface as a final `llm.Error` event before close.
//
// Use the channel for the UI fast path (Delta → render incrementally) and
// the collector for the agent-loop shape that needs the final tool-call
// list. Callers must drain the channel before invoking `collect` —
// otherwise the producing goroutine blocks waiting for the channel sink.
//
// Example — text-only consumer:
//
//	events, _ := chat.New("anthropic:claude-opus-4-7") |> chat.AskStream("...")
//	for evt in events
//	    switch evt
//	        when llm.Delta
//	            print(e.Body)
//
// Example — agent loop:
//
//	events, collect := chat.New(...) |> ... |> chat.AskStream(prompt)
//	for evt in events
//	    if evt is llm.Delta as d
//	        ui.OnText(d.Body)
//	comp, err := collect() onerr return empty, error
//	if chat.HasToolCalls(comp)
//	    ...
func AskStream(c Client, prompt string) (chan llm.StreamEvent, func() (Completion, error)) {
	return SendStream(User(c, prompt))
}

// SendStream is the no-prompt-appended variant of AskStream — for callers that
// already populated `c.messages` (e.g. via `chat.Messages` for an agent loop).
// Same return contract as AskStream: a channel of events plus a `collect`
// closure for the assembled Completion.
func SendStream(c Client) (chan llm.StreamEvent, func() (Completion, error)) {
	out := make(chan llm.StreamEvent, 16)
	done := make(chan streamFinal, 1)
	sink := func(evt llm.StreamEvent) {
		out <- evt
	}
	c = StreamEvents(c, sink)
	go func() {
		comp, sErr := executeStreamRaw(c)
		if sErr != nil {
			out <- llm.Error{Message: fmt.Sprintf("%v", sErr)}
		}
		close(out)
		done <- streamFinal{Completion: comp, Err: sErr}
	}()
	collect := func() (Completion, error) {
		res := <-done
		return res.Completion, res.Err
	}
	return out, collect
}

// AskJSON adds a user message, executes the request, and decodes the reply into T.
//
// For struct targets, JSONMode is forced so the provider returns valid JSON. For
// string-backed enum targets (Go `type T string`), the bare reply (e.g. "restart")
// is JSON-quoted before unmarshaling so `ParseT`-equivalent decoding succeeds.
//
// Example:
//
//	verdict := chat.New("anthropic:claude-opus-4-7")
//	    |> chat.System("Choose one of: restart, rollback, page_human, ignore.")
//	    |> chat.AskJSON of Verdict from "workload: {alert.workload}"
//	    onerr return Verdict.PageHuman, error
func AskJSON[T any](c Client, prompt string) (T, error) {
	zero := *new(T)
	elemType := reflect.TypeOf(zero)
	if elemType == nil {
		return zero, errors.New("chat.AskJSON: cannot determine target type (T must not be an interface)")
	}
	if elemType.Kind() != reflect.String {
		c = JSONMode(c)
	}
	reply, askErr := Ask(c, prompt)
	if askErr != nil {
		return zero, askErr
	}
	body := kukistring.TrimSpace(reply)
	if elemType.Kind() == reflect.String {
		encoded, encErr := json.Bytes(body)
		if encErr != nil {
			return zero, encErr
		}
		body = string(encoded)
	}
	err_1 := json.ParseInto(body, &zero)
	if err_1 != nil {
		err_1 = fmt.Errorf("chat.AskJSON: decode failed for reply : %w", err_1)
		var _zero0 T
		return _zero0, err_1
	}
	return zero, nil
}

